// Set your minimum dBZ cutoff here (e.g. 30 = light/moderate rain, 40 = strong 10 GHz scatter cores)
let minDbz = flow.get("minDbz") || 30;

let data = JSON.parse(msg.payload);
let nowSec = Math.floor(Date.now() / 1000);

// Filter out any cell whose peak dBZ (extracted from Type, e.g. "RN42") is below minDbz
let filtered = (data.acList || []).filter(ac => {
    let dbz = parseInt((ac.Type || "").replace(/[^0-9]/g, ""), 10) || 0;
    return dbz >= minDbz;
});

let states = filtered.map((ac, idx) => {
    let hexIcao = (0x4F0001 + idx).toString(16).toUpperCase();
    return [
        hexIcao,              // 0 -> Index 1 in AirScout: Hex ICAO (e.g. 400001)
        ac.Call,              // 1 -> Index 2 in AirScout: Callsign (e.g. RN400001)
        ac.Lat,               // 2 -> Index 3 in AirScout: Latitude
        ac.Long,              // 3 -> Index 4 in AirScout: Longitude
        ac.Alt,               // 4 -> Index 5 in AirScout: Live Bright-Band Altitude (ft)
        ac.Spd,               // 5 -> Index 6 in AirScout: Speed (kts)
        ac.Trak,              // 6 -> Index 7 in AirScout: Track (deg)
        ac.Type,              // 7 -> Index 8 in AirScout: Aircraft Type (i.e. RN42)
        ac.Reg,               // 8 -> Index 9 in AirScout: Registration (e.g. RN4000014212)
        nowSec                // 9 -> Index 10 in AirScout: UTC Timestamp (seconds)
    ];
});

msg.payload = states;
msg.headers = { "Content-Type": "application/json" };
return msg;
